import { notify } from 'src/components/notifications/notify';
import { tol } from 'src/boot/tolgee';

/**
 * Runs `task()` while listening for `app:backend-unavailable` events on the
 * window (dispatched by ApiClient.ts / custom-axios-instance.ts on network
 * errors or 503s). If any fired during the task, surfaces the
 * `workflow_partial_data_warning` toast.
 *
 * Pairs with the global `BackendUnavailableBanner` — that one fires for any
 * failure app-wide; this gives the workflow pages a context-specific toast
 * so the user sees a workflow-flavoured signal even when the dropdown store
 * has already swallowed the underlying error silently.
 */

interface BackendUnavailableDetail {
  url?: string;
  status?: number;
  reason?: string;
  source?: string;
  timestamp?: number;
}

/**
 * Extracts a short service hint from a URL: the leading hostname subdomain
 * (e.g. `operator`, `api`, `auth`) plus the first path segment. Falls back
 * to the raw URL on parse failure. Pure utility, exported for tests.
 */
export function deriveFailureLabel(url: string | undefined): string {
  if (!url) return '(no url)';
  try {
    const parsed = new URL(url, 'http://placeholder.invalid');
    const host = parsed.hostname.replace('placeholder.invalid', '');
    const sub = host.split('.').find((part) =>
      ['operator', 'auth', 'api', 'docnet', 'import-email'].includes(part),
    );
    const firstPathSeg = parsed.pathname.split('/').filter(Boolean)[0];
    if (sub && firstPathSeg) return `${sub}/${firstPathSeg}`;
    if (sub) return sub;
    if (firstPathSeg) return firstPathSeg;
    return host || url;
  } catch {
    return url;
  }
}

export async function runWithBackendUnavailableWarning<T>(
  task: () => Promise<T>,
  contextTag: string,
): Promise<T> {
  const failures: BackendUnavailableDetail[] = [];
  const onUnavailable = (ev: Event) => {
    const detail = ((ev as CustomEvent)?.detail ?? {}) as BackendUnavailableDetail;
    failures.push(detail);
    console.warn(
      `[${contextTag}] caught app:backend-unavailable for ${deriveFailureLabel(detail.url)}`,
      detail,
    );
  };

  if (typeof window !== 'undefined') {
    window.addEventListener('app:backend-unavailable', onUnavailable);
    console.info(
      `[${contextTag}] backend-availability monitor armed for workflow init`,
    );
  }

  try {
    return await task();
  } finally {
    if (typeof window !== 'undefined') {
      window.removeEventListener('app:backend-unavailable', onUnavailable);
    }
    if (failures.length > 0) {
      const labels = failures.map((f) => deriveFailureLabel(f.url));
      const summary = labels.join(', ');
      console.warn(
        `[${contextTag}] init finished — ${failures.length} backend call(s) failed: ${summary}. Showing partial-data warning toast.`,
        { failures },
      );
      try {
        notify.warning(tol.t('workflow_partial_data_warning'));
      } catch (err) {
        console.error(`[${contextTag}] notify.warning threw:`, err);
      }
    } else {
      console.info(
        `[${contextTag}] backend-availability monitor cleared cleanly — no toast needed`,
      );
    }
  }
}
