/**
 * Shared card filtering logic for workflow designers (v2 and advanced).
 *
 * Both designers use the same card picker dialog with identical filter logic.
 * These pure functions operate on the filteredCardsList reactive object.
 */

/**
 * Filters cards to show only the latest version of each card.
 */
export function filterLatestCardVersion(filteredCardsList: any): void {
  filteredCardsList.cards = filteredCardsList.cards.filter(
    (card: any) => card.card_version == card.latest_version,
  );
}

/**
 * Filters out deprecated cards.
 */
export function filterDeprecatedCards(filteredCardsList: any): void {
  filteredCardsList.cards = filteredCardsList.cards.filter(
    (card: any) => card.deprecated == false,
  );
}

/**
 * Filters out version 1 when/and condition cards (used by advanced designer
 * which only supports v2+ condition cards).
 */
export function filterVersionOneConditionCards(filteredCardsList: any): void {
  filteredCardsList.cards = filteredCardsList.cards.filter((card: any) => {
    const isConditionCard = card.when_condition === true || card.and_condition === true;
    const isVersionOne = card.card_version === 1;
    return !(isConditionCard && isVersionOne);
  });
}

/**
 * Filters out cards that use workflow variables (variable_name / tag_name).
 * These cards are only usable in the advanced designer where variables can be defined.
 */
export function filterWorkflowVariableCards(filteredCardsList: any): void {
  filteredCardsList.cards = filteredCardsList.cards.filter((card: any) => {
    if (!card.variables?.length) return true;
    return !card.variables.some(
      (v: any) => v.display_name === 'variable_name' || v.display_name === 'tag_name',
    );
  });
}

/**
 * Searches cards by translated text within a given array.
 * Returns filtered cards matching the search value (case-insensitive).
 */
export function searchCardsInList(
  cards: any[],
  searchValue: string,
  translateFn: (key: string) => string,
): any[] {
  if (!searchValue || searchValue.length === 0) return cards;
  const lower = searchValue.toLowerCase();
  return cards.filter((card: any) =>
    translateFn(card.text).toLowerCase().includes(lower),
  );
}

/**
 * Resolves which cards to show based on search value and selected subcategory.
 * Shared by both v2 and advanced workflow designers.
 */
export function resolveCardSearch(
  searchValue: string,
  selectedSubCategory: boolean,
  subCategoryCards: any[] | null,
  allCards: any[],
  translateFn: (key: string) => string,
): any[] {
  if (searchValue && searchValue.length > 0 && selectedSubCategory && subCategoryCards) {
    return searchCardsInList(subCategoryCards, searchValue, translateFn);
  } else if (searchValue && searchValue.length > 0) {
    return searchCardsInList(allCards, searchValue, translateFn);
  } else if (selectedSubCategory && subCategoryCards) {
    return subCategoryCards;
  } else {
    return allCards;
  }
}

/**
 * Assigns a category color to all cards in an array (returns new array).
 */
export function assignCategoryColor(
  cards: any[],
  svgBackgroundColor: string,
): any[] {
  return cards.map((card: any) => ({
    ...card,
    svg_background_color: svgBackgroundColor,
  }));
}
